package com.ptms.controller;import com.ptms.dto.*;import com.ptms.service.*;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.util.*;
@RestController @RequestMapping("/api/tickets") public class TicketInventoryController{private final TicketInventoryService s;private final LocalTicketPhotoRecognitionService recognition;public TicketInventoryController(TicketInventoryService s,LocalTicketPhotoRecognitionService recognition){this.s=s;this.recognition=recognition;}@GetMapping public List<TicketDto>all(){return s.all();}@GetMapping("/remaining") public List<TicketDto>remaining(){return s.remaining();}@PostMapping public TicketDto create(@Valid @RequestBody TicketDto q){return s.create(q);}@PutMapping("/{id}") public TicketDto update(@PathVariable Long id,@Valid @RequestBody TicketDto q){return s.update(id,q);}@DeleteMapping("/{id}") public void delete(@PathVariable Long id){s.delete(id);}@PostMapping("/bulk-scan") public List<TicketDto>bulk(@Valid @RequestBody BulkTicketScanRequest q){return s.bulk(q);}@PostMapping("/bulk") public List<TicketDto>bulkItems(@Valid @RequestBody List<@Valid BulkTicketItemRequest> q){return s.bulkItems(q);}@PostMapping(value="/recognize-photo",consumes="multipart/form-data") public TicketPhotoRecognitionResponse recognizePhoto(@RequestParam("image") MultipartFile image){return recognition.recognize(image);}}
